function maxSubarraySumCircular(nums: number[]): number {
  let total = 0;

  // Кадане для максимума: лучший обычный (не кольцевой) подмассив
  let curMax = 0;
  let bestMax = -Infinity;

  // Кадане для минимума: самый «плохой» подмассив,
  // который выгоднее всего выкинуть из середины
  let curMin = 0;
  let bestMin = Infinity;

  for (const x of nums) {
    curMax = Math.max(x, curMax + x);
    bestMax = Math.max(bestMax, curMax);

    curMin = Math.min(x, curMin + x);
    bestMin = Math.min(bestMin, curMin);

    total += x;
  }

  // Все числа отрицательные: total - bestMin = 0 соответствовал бы
  // пустому подмассиву, а он запрещён. Ответ — просто наибольший элемент
  if (bestMax < 0) return bestMax;

  // Либо обычный отрезок, либо отрезок «через край»:
  // весь массив минус минимальный отрезок посередине
  return Math.max(bestMax, total - bestMin);
}

// Время: O(n) — один проход
// Память: O(1)
